import 'package:flutter/material.dart';
import 'package:google_fonts/google_fonts.dart';

import 'my_path_roadmap_palette.dart';

/// Placeholder shown while the student's active path is being fetched — or
/// being generated by the AI engine after the wizard completes.
class MyPathGeneratingView extends StatefulWidget {
  const MyPathGeneratingView({
    super.key,
    required this.title,
    required this.subtitle,
  });

  final String title;
  final String subtitle;

  @override
  State<MyPathGeneratingView> createState() => _MyPathGeneratingViewState();
}

class _MyPathGeneratingViewState extends State<MyPathGeneratingView>
    with SingleTickerProviderStateMixin {
  late final AnimationController _pulse;

  @override
  void initState() {
    super.initState();
    _pulse = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 1500),
    )..repeat(reverse: true);
  }

  @override
  void dispose() {
    _pulse.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Center(
      child: Padding(
        padding: const EdgeInsets.all(32),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Container(
              padding: const EdgeInsets.all(24),
              decoration: BoxDecoration(
                shape: BoxShape.circle,
                gradient: const LinearGradient(
                  colors: [
                    MyPathRoadmapColors.headerDarkMid,
                    MyPathRoadmapColors.headerDarkBottom,
                  ],
                ),
                border: Border.all(
                  color: MyPathRoadmapColors.mint.withValues(alpha: .5),
                  width: 2,
                ),
                boxShadow: [
                  BoxShadow(
                    color: MyPathRoadmapColors.mint.withValues(alpha: .35),
                    blurRadius: 24,
                    spreadRadius: 2,
                  ),
                ],
              ),
              child: AnimatedBuilder(
                animation: _pulse,
                builder: (context, child) {
                  return Transform.scale(
                    scale: .95 + _pulse.value * .1,
                    child: Icon(
                      Icons.smart_toy_outlined,
                      size: 46,
                      color: Color.lerp(
                        MyPathRoadmapColors.mint,
                        Colors.white,
                        _pulse.value * .5,
                      ),
                    ),
                  );
                },
              ),
            ),
            const SizedBox(height: 20),
            Text(
              widget.title,
              textAlign: TextAlign.center,
              style: GoogleFonts.inter(
                fontSize: 16,
                fontWeight: FontWeight.w900,
                color: MyPathRoadmapColors.headerDarkMid,
              ),
            ),
            const SizedBox(height: 8),
            AnimatedBuilder(
              animation: _pulse,
              builder: (context, _) {
                return Opacity(
                  opacity: .55 + _pulse.value * .45,
                  child: Text(
                    widget.subtitle,
                    textAlign: TextAlign.center,
                    style: GoogleFonts.inter(
                      fontSize: 12,
                      height: 1.6,
                      fontWeight: FontWeight.w500,
                      color: MyPathRoadmapColors.slateBody,
                    ),
                  ),
                );
              },
            ),
            const SizedBox(height: 22),
            SizedBox(
              width: 180,
              child: ClipRRect(
                borderRadius: BorderRadius.circular(999),
                child: Container(
                  height: 8,
                  color: Colors.black.withValues(alpha: .06),
                  padding: const EdgeInsets.all(1.5),
                  child: AnimatedBuilder(
                    animation: _pulse,
                    builder: (context, _) {
                      return FractionallySizedBox(
                        alignment: Alignment.centerLeft,
                        widthFactor: .15 + _pulse.value * .75,
                        child: Container(
                          decoration: BoxDecoration(
                            borderRadius: BorderRadius.circular(999),
                            gradient: const LinearGradient(
                              colors: [
                                Color(0xFF10B981),
                                MyPathRoadmapColors.mint,
                                MyPathRoadmapColors.teal,
                              ],
                            ),
                          ),
                        ),
                      );
                    },
                  ),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}
